#!/usr/bin/env python3
"""Render task-oriented, crawlable HTML guides from reviewed editorial content."""
import argparse,html,json,re
from site_shell import shared_shell
from pathlib import Path

def render(config_path,output):
    config=json.loads(Path(config_path).read_text());out=Path(output);out.mkdir(parents=True,exist_ok=True)
    brand=config['brand'];base=config['base'];hub=config['hub'];guides=config['guides'];e=html.escape
    colors=config['colors'];css='''*{box-sizing:border-box}body{margin:0;font:17px/1.8 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--bg);color:var(--ink)}a{color:var(--accent);text-underline-offset:4px}a:hover{text-decoration-thickness:2px}header,footer{border-block:1px solid var(--line)}nav{max-width:1100px;margin:auto;padding:20px 24px;display:flex;align-items:center;gap:24px;flex-wrap:wrap}nav strong{font-size:24px;margin-right:auto}nav a{text-decoration:none}main{max-width:900px;margin:auto;padding:48px 24px 70px}.eyebrow,.breadcrumbs{font-size:14px;color:var(--muted)}h1{font-size:clamp(32px,5vw,52px);line-height:1.15;letter-spacing:-.035em;margin:20px 0}h2{font-size:28px;line-height:1.3;margin:42px 0 14px}h3{font-size:21px;line-height:1.4}p,li{overflow-wrap:anywhere}.lead{font-size:21px;color:var(--muted)}.note,.toc,.card{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:22px;margin:24px 0}.note{border-left:4px solid var(--accent)}.toc ul{padding-left:22px;margin-bottom:0}.toc a{font-size:16px}pre{background:var(--code);color:var(--codeink);border:1px solid var(--line);padding:22px;border-radius:8px;overflow-x:auto;line-height:1.65;font-size:14px;max-width:100%;tab-size:2}code,kbd{font-family:ui-monospace,SFMono-Regular,Consolas,monospace}p code,li code{font-size:.88em;background:var(--surface);padding:2px 5px;border-radius:3px}kbd{border:1px solid var(--line);border-bottom-width:3px;padding:2px 6px;border-radius:4px;background:var(--surface);font-size:14px}.table-wrap{overflow-x:auto;max-width:100%}table{width:100%;border-collapse:collapse;font-size:15px}th,td{padding:12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{background:var(--surface)}video,img{max-width:100%;height:auto}video{border:1px solid var(--line);border-radius:8px;background:#20233a;width:100%}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.grid .card{margin:0}.cta{margin-top:42px;padding:28px;background:var(--surface);border:1px solid var(--line);border-radius:10px}.button{display:inline-block;background:var(--accent);color:var(--bg);padding:10px 18px;border-radius:6px;text-decoration:none;font-weight:650}.updated,footer{color:var(--muted);font-size:14px}footer>div{max-width:1100px;margin:auto;padding:24px}.skip{position:absolute;left:-9999px}.skip:focus{left:12px;top:12px;background:var(--surface);padding:12px}a:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:4px}@media(max-width:640px){main{padding:30px 18px 48px}nav{gap:15px;padding:16px 18px;font-size:14px}.grid{grid-template-columns:1fr}.lead{font-size:19px}h2{font-size:25px}pre{padding:15px;font-size:13px}.note,.toc,.card{padding:18px}}'''
    variables=':root{'+''.join('--'+k+':'+v+';' for k,v in colors.items())+'}\n'
    css_path=out/config['css_file'];css_path.parent.mkdir(parents=True,exist_ok=True);css_path.write_text(variables+css)
    def shell(path,title,description,body,article=False):
        url=base+path
        schemas=[{'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':brand,'item':base+'/'},{'@type':'ListItem','position':2,'name':'Practical guides','item':base+hub}]+([{'@type':'ListItem','position':3,'name':title,'item':url}] if article else [])}]
        if article:schemas.append({'@context':'https://schema.org','@type':'TechArticle','headline':title,'description':description,'url':url,'dateModified':config.get('updated_on','2026-10-27'),'author':{'@type':'Organization','name':brand},'inLanguage':'en'})
        schema=''.join('<script type="application/ld+json">'+json.dumps(s,ensure_ascii=False).replace('<','\\u003c')+'</script>' for s in schemas)
        return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} — {e(brand)}</title><meta name="description" content="{e(description,quote=True)}"><link rel="canonical" href="{url}"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:title" content="{e(title,quote=True)} — {e(brand)}"><meta property="og:description" content="{e(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{base+config['social']}"><link rel="icon" href="{config['icon']}"><link rel="stylesheet" href="{config['css_url']}">{schema}</head><body><a class="skip" href="#main">Skip to content</a><header><nav aria-label="Main navigation"><strong><a href="/">{e(brand)}</a></strong><a href="{hub}">Practical guides</a><a href="/changelog.html">What’s new</a><a href="{config['docs']}">Documentation</a><a href="{config['cta']}">{e(config['cta_label'])} →</a></nav></header><main id="main">{body}</main><footer><div>{e(brand)} · Practical examples, explicit scope, reproducible checks. <a href="/">Product overview</a> · Part of the <a href="https://spedo.dev/">Spedo family</a>.</div></footer></body></html>'''
    def card(guide):return '<article class="card"><h2><a href="'+guide['path']+'">'+e(guide['title'])+'</a></h2><p>'+e(guide['description'])+'</p></article>'
    for guide in guides:
        toc=[]
        def heading(match):
            label=re.sub('<[^>]+>','',match[1]);slug=re.sub(r'[^a-z0-9]+','-',label.lower()).strip('-');toc.append((slug,label));return '<h2 id="'+slug+'">'+match[1]+'</h2>'
        article_body=re.sub(r'<h2>(.*?)</h2>',heading,guide['body'],flags=re.S)
        contents='<aside class="toc" aria-label="On this page"><strong>On this page</strong><ul>'+''.join('<li><a href="#'+slug+'">'+e(label)+'</a></li>' for slug,label in toc)+'</ul></aside>'
        body='<p class="breadcrumbs"><a href="/">'+e(brand)+'</a> / <a href="'+hub+'">Practical guides</a></p><p class="eyebrow">'+e(guide['category'])+'</p><h1>'+e(guide['title'])+'</h1><p class="lead">'+e(guide['description'])+'</p><p class="updated">Updated '+e(config.get('updated_label','October 27, 2026'))+' · '+e(guide['scope'])+'</p>'+contents+article_body+'<section class="cta"><h2>Try it on your own workload</h2><p>'+e(config['cta_text'])+'</p><a class="button" href="'+config['cta']+'">'+e(config['cta_label'])+' →</a></section><section><h2>Continue the investigation</h2><div class="grid">'+''.join(card(g) for g in guides if g!=guide)+'</div></section>'
        dest=out/guide['file'];dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(shared_shell(shell(guide['path'],guide['title'],guide['description'],body,True)))
    body='<p class="eyebrow">'+e(brand)+' / practical guides</p><h1>'+e(config['hub_title'])+'</h1><p class="lead">'+e(config['hub_description'])+'</p><div class="grid">'+''.join(card(g) for g in guides)+'</div><aside class="note">'+e(config['hub_note'])+'</aside>'
    dest=out/config['hub_file'];dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(shared_shell(shell(hub,config['hub_title'],config['hub_description'],body)))
    return [hub]+[g['path'] for g in guides]
if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('content');parser.add_argument('output');args=parser.parse_args();print(json.dumps(render(args.content,args.output)))
